 '--syntax-theme','--tabs','--true-color','--whitespace-error-style','--width','--word-diff-regex','--wrap-left-symbol','--wrap-max-lines','--wrap-right-percent','--wrap-right-prefix-symbol','--wrap-right-symbol','--zero-style','--24-bit-color'
}
BOOL_FLAGS = {
 '--color-only','--diff-highlight','--diff-so-fancy','--dark','--light','--hyperlinks','--keep-plus-minus-markers','--line-numbers','--list-languages','--list-syntax-themes','--navigate','--no-gitconfig','--parse-ansi','--raw','--relative-paths','--show-colors','--show-config','--show-syntax-themes','--show-themes','--side-by-side'
}
ALL_FLAGS = VALUE_FLAGS | BOOL_FLAGS | {'--help','--version'}

def strip_ansi(s): return ANSI_RE.sub('', s)
def chomp(line): return line[:-1] if line.endswith('\n') else line
def color(c, s): return c + s + RESET

def parse_args(argv):
    opts={
        'color_only':False,'raw':False,'line_numbers':False,'side_by_side':False,
        'keep_markers':False,'dark':False,'light':False,'paging':'auto','width':80,
        'width_variable':False,'minus_style':'default','plus_style':'default','zero_style':'syntax',
        'file_style':'blue','hunk_header_style':'default','no_gitconfig':False,
        'config':None,'diff_so_fancy':False,'diff_highlight':False,'navigate':False,
    }
    pos=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a == '--':
            pos.extend(argv[i+1:]); break
        if a in ('--help',): opts['help']='long'; i+=1; continue
        if a == '-h': opts['help']='short'; i+=1; continue
        if a in ('--version','-V'): opts['version']=True; i+=1; continue
        if a == '-n': opts['line_numbers']=True; i+=1; continue
        if a == '-s': opts['side_by_side']=True; i+=1; continue
        if a == '-@':
            if i+1>=len(argv): return None, [], missing_error('-@ <STRING>')
            opts['diff_args']=argv[i+1]; i+=2; continue
        if a.startswith('-@') and len(a)>2:
            opts['diff_args']=a[2:]; i+=1; continue
        if a.startswith('--'):
            if '=' in a:
                flag,val=a.split('=',1)
            else:
                flag,val=a,None
            if flag not in ALL_FLAGS:
                return None, [], unknown_error(a)
            if flag in VALUE_FLAGS:
                if val is None:
                    if i+1>=len(argv): return None, [], missing_error(flag)
                    val=argv[i+1]; i+=1
                set_value(opts, flag, val)
            else:
                if val is not None:
                    return None, [], unknown_error(a)
                set_bool(opts, flag)
            i+=1; continue
        if a.startswith('-') and a != '-':
            return None, [], unknown_error(a)
        pos.append(a); i+=1
    if len(pos)>2:
        return None, [], unexpected_pos_error(pos[2])
    if opts.get('light') and opts.get('dark'):
        return None, [], (2, '', '--light and --dark cannot be used together.\n')
    if opts.get('paging') not in ('auto','always','never'):
        bad=opts.get('paging')
        return None, [], (2, '', f"\033[1m\033[31merror:\033[0m invalid value '\033[33m{bad}\033[0m' for '\033[1m--paging <auto|always|never>\033[0m'\n  [possible values: \033[32mauto\033[0m, \033[32malways\033[0m, \033[32mnever\033[0m]\n\nFor more information, try '\033[1m--help\033[0m'.\n")
    return opts, pos, None

def set_bool(opts, flag):
    m={'--color-only':'color_only','--raw':'raw','--line-numbers':'line_numbers','--side-by-side':'side_by_side','--keep-plus-minus-markers':'keep_markers','--dark':'dark','--light':'light','--no-gitconfig':'no_gitconfig','--diff-so-fancy':'diff_so_fancy','--diff-highlight':'diff_highlight','--navigate':'navigate'}
    if flag in m: opts[m[flag]]=True
    else: opts[flag[2:].replace('-','_')]=True

def set_value(opts, flag, val):
    if flag=='--paging': opts['paging']=val
    elif flag=='--width':
        if val=='variable': opts['width_variable']=True; opts['width']=None
        else:
            try:
                # accept simple arithmetic of the form N-M used by delta docs
                if re.fullmatch(r'\d+\s*-\s*\d+', val):
                    a,b=re.split(r'\s*-\s*', val); opts['width']=max(0,int(a)-int(b))
                else: opts['width']=int(val)
            except Exception: opts['width']=80
    elif flag=='--config': opts['config']=val
    elif flag=='--minus-style': opts['minus_style']=val
    elif flag=='--plus-style': opts['plus_style']=val
    elif flag=='--zero-style': opts['zero_style']=val
    elif flag=='--file-style': opts['file_style']=val
    elif flag=='--hunk-header-style': opts['hunk_header_style']=val
    elif flag=='--right-arrow': opts['right_arrow']=val
    elif flag=='--generate-completion': opts['generate_completion']=val
    elif flag=='--inspect-raw-lines': opts['inspect_raw_lines']=val
    else: opts[flag[2:].replace('-','_')]=val

def unknown_error(arg):
    tip="\n  \033[32mtip:\033[0m a similar argument exists: '\033[32m--blame-code-style\033[0m'\n" if arg.startswith('--') else ''
    return (2,'',f"\033[1m\033[31merror:\033[0m unexpected argument '\033[33m{arg}\033[0m' found\n{tip}\n{USAGE_OPTIONS}")
def unexpected_pos_error(arg):
    return (2,'',f"\033[1m\033[31merror:\033[0m unexpected argument '\033[33m{arg}\033[0m' found\n\n{USAGE_LONG}")
def missing_error(flag):
    return (2,'',f"\033[1m\033[31merror:\033[0m a value is required for '{flag}' but none was supplied\n\nFor more information, try '\033[1m--help\033[0m'.\n")

def read_config(opts):
    if opts.get('no_gitconfig'): return
    paths=[]
    if opts.get('config'): paths.append(Path(opts['config']).expanduser())
    else:
        paths += [Path.cwd()/'.git'/'config', Path.home()/'.gitconfig']
    for p in paths:
        try: text=p.read_text(errors='ignore')
        except Exception: continue
        section=''
        for raw in text.splitlines():
            line=raw.strip()
            if not line or line.startswith(('#',';')): continue
            if line.startswith('[') and line.endswith(']'):
                section=line[1:-1].strip().lower(); continue
            if not (section=='delta' or section.startswith('delta ')): continue
            if '=' in line: k,v=[x.strip() for x in line.split('=',1)]
            else: k,v=line,'true'
            v=v.strip('"\'')
            key=k.lower().replace('_','-')
            truth=v.lower() in ('true','yes','on','1')
            if key=='line-numbers': opts['line_numbers']=truth
            elif key=='side-by-side': opts['side_by_side']=truth
            elif key=='keep-plus-minus-markers': opts['keep_markers']=truth
            elif key=='dark': opts['dark']=truth
            elif key=='light': opts['light']=truth
            elif key=='minus-style': opts['minus_style']=v
            elif key=='plus-style': opts['plus_style']=v
            elif key=='zero-style': opts['zero_style']=v
            elif key=='file-style': opts['file_style']=v
            elif key=='hunk-header-style': opts['hunk_header_style']=v
            elif key=='width':
                try: opts['width']=int(v)
                except: pass

# styling helpers
def is_raw_style(s): return 'raw' in str(s).split()
def has_word_style(s, word): return word in str(s).replace('"','').split()

def ansi_file(opts, text):
    if is_raw_style(opts.get('file_style','')): return text
    return BLUE + text + RESET

def ansi_hunk_dec(opts, text):
    # diff-so-fancy uses magenta hunk decoration; default blue.
    c = MAGENTA if opts.get('diff_so_fancy') else BLUE
    return c + text + RESET

def text_color(opts): return LIGHT_TEXT if opts.get('light') else DARK_TEXT

def style_zero(opts, text):
    if is_raw_style(opts.get('zero_style','')): return text
    if has_word_style(opts.get('zero_style',''), 'normal'): return text
    return text_color(opts) + text + RESET

def fill_seq(bg, opts):
    if opts.get('width_variable'): return ''
    return f'\033[48;5;{bg}m\033[0K\033[0m'

def bg_colors(opts):
    if opts.get('light'):
        return {'minus':224,'minus_emph':217,'plus':194,'plus_emph':157,'plus_fg':236}
    return {'minus':52,'minus_emph':124,'plus':22,'plus_emph':28,'plus_fg':231}

def changed_spans(old, new):
    # Return expanded changed spans suitable for word-level highlighting, or None.
    if not old or not new: return None
    pref=0
    while pref < len(old) and pref < len(new) and old[pref]==new[pref]: pref+=1
    suff=0
    while suff < len(old)-pref and suff < len(new)-pref and old[len(old)-1-suff]==new[len(new)-1-suff]: suff+=1
    if pref==0 and suff==0: return None
    oe=len(old)-suff; ne=len(new)-suff
    os=pref; ns=pref
    word=re.compile(r'[A-Za-z0-9_]+')
    # expand to surrounding word in each string
    for m in word.finditer(old):
        if m.start() <= os < m.end() or m.start() < oe <= m.end() or (os==oe and m.start()<=os<=m.end()):
            os=min(os,m.start()); oe=max(oe,m.end()); break
    for m in word.finditer(new):
        if m.start() <= ns < m.end() or m.start() < ne <= m.end() or (ns==ne and m.start()<=ns<=m.end()):
            ns=min(ns,m.start()); ne=max(ne,m.end()); break
    if os==0 and oe==len(old) and ns==0 and ne==len(new): return None
    if os==oe and ns==ne: return None
    return (os,oe,ns,ne)

def style_minus(opts, text, span=None, marker=''):
    sopt=str(opts.get('minus_style',''))
    content=marker+text
    if is_raw_style(sopt): return content
    if has_word_style(sopt,'red') and '52' not in sopt: return '\033[31m'+content+RESET
    c=bg_colors(opts); bg=c['minus']; emph=c['minus_emph']
    if marker:
        # marker participates in normal background; span indices refer to text
        off=len(marker)
    else: off=0
    if not span:
        return f'\033[48;5;{bg}m{content}{RESET}' + fill_seq(bg, opts)
    a,b=span[0]+off, span[1]+off
    out=f'\033[48;5;{bg}m'
    if a>0: out += content[:a]
    out += f'\033[48;5;{emph}m' + content[a:b]
    out += f'\033[48;5;{bg}m' + content[b:]
    return out + RESET + fill_seq(bg, opts)

def style_plus(opts, text, span=None, marker=''):
    sopt=str(opts.get('plus_style',''))
    content=marker+text
    if is_raw_style(sopt): return content
    if has_word_style(sopt,'green') and '22' not in sopt: return '\033[32m'+content+RESET
    c=bg_colors(opts); bg=c['plus']; emph=c['plus_emph']; fg=c['plus_fg']
    off=len(marker)
    if not span:
        if marker:
            return f'\033[48;5;{bg}m{marker}\033[38;5;{fg}m{text}{RESET}' + fill_seq(bg, opts)
        return f'\033[48;5;{bg};38;5;{fg}m{text}{RESET}' + fill_seq(bg, opts)
    a,b=span[2]+off, span[3]+off
    out=f'\033[48;5;{bg};38;5;{fg}m'
    if marker:
        out=f'\033[48;5;{bg}m{marker}\033[38;5;{fg}m'
    if a>0: out += content[off:a] if marker else content[:a]
    out += f'\033[48;5;{emph}' + (f';38;5;{fg}' if not marker else '') + 'm' + content[a:b]
    out += f'\033[48;5;{bg}m' + content[b:]
    return out + RESET + fill_seq(bg, opts)

def style_minus_coloronly(opts, text, span=None):
    # text includes the leading '-'.
    body=text[1:]
    if span:
        c=bg_colors(opts); bg=c['minus']; emph=c['minus_emph']
        a,b=span[0],span[1]
        out=f'\033[48;5;{bg}m-'
        out += body[:a] + f'\033[48;5;{emph}m' + body[a:b] + f'\033[48;5;{bg}m' + body[b:]
        return out + RESET + fill_seq(bg, opts)
    return style_minus(opts, body, None, marker='-')

def style_plus_coloronly(opts, text, span=None):
    body=text[1:]
    return style_plus(opts, body, span, marker='+')

def fmt_num(n):
    if n is None: return '    '
    s=str(n)
    if len(s)>=4: return s
    # center-ish width four, matching common delta output for small numbers
    return s.center(4)

def line_prefix(opts, oldn, newn, kind):
    if not opts.get('line_numbers'): return ''
    if kind=='context':
        return BLUE + GREY + fmt_num(oldn) + BLUE + '⋮' + GREY + fmt_num(newn) + BLUE + '│'
    if kind=='minus':
        return BLUE + REDNUM + fmt_num(oldn) + BLUE + '⋮' + GREENNUM + fmt_num(None) + BLUE + '│' + RESET
    if kind=='plus':
        return BLUE + REDNUM + fmt_num(None) + BLUE + '⋮' + GREENNUM + fmt_num(newn) + BLUE + '│'
    return ''

def parse_hunk_header(line):
    s=strip_ansi(chomp(line))
    m=re.match(r'@@@?\s+-(\d+)(?:,(\d+))?\s+\+(\d+)(?:,(\d+))?\s+@@@?\s?(.*)$', s)
    if not m: return 1,1,''
    return int(m.group(1)), int(m.group(3)), m.group(5) or ''

def display_path(p, git_context=False):
    p=p.strip()
    if p=='/dev/null': return p
    # remove timestamps after filenames in ordinary diff output
    if '\t' in p: p=p.split('\t',1)[0]
    if git_context and (p.startswith('a/') or p.startswith('b/')): p=p[2:]
    if p.startswith('/'):
        p=p[1:]
    return p

def file_header(opts, minus, plus, git_context=False):
    m=display_path(minus, git_context); p=display_path(plus, git_context)
    if m=='/dev/null': label='added: ' + p
    elif p=='/dev/null': label='removed: ' + m
    elif m==p: label=m
    else: label=m + ' ' + opts.get('right_arrow','⟶  ') + ' ' + p
    width = opts.get('width') or max(0,len(label))
    if opts.get('diff_so_fancy'):
        return '\n' + '\033[1;33m' + ('━'*width) + RESET + '\n' + '\033[38;5;11m' + label + RESET + '\n' + '\033[1;33m' + ('━'*width) + RESET + '\n'
    return '\n' + ansi_file(opts,label) + '\n' + BLUE + ('─'*width) + RESET + '\n'

def hunk_box(opts, plus_start, ctx, raw_line=None):
    if is_raw_style(opts.get('hunk_header_style','')) and raw_line is not None:
        middle=chomp(strip_ansi(raw_line))+' '
        top='─'*len(middle)
        return '\n' + ansi_hunk_dec(opts,top)+ansi_hunk_dec(opts,'┐')+'\n' + middle + ansi_hunk_dec(opts,'│')+'\n' + ansi_hunk_dec(opts,top)+ansi_hunk_dec(opts,'┘')+'\n'
    label_num=str(plus_start)
    if ctx:
        plain=f'{label_num}: {ctx} '
        mid=BLUE+label_num+RESET+': '+style_zero(opts,ctx+' ')+ansi_hunk_dec(opts,'│')
    else:
        plain=f'{label_num}: '
        mid=BLUE+label_num+RESET+': '+ansi_hunk_dec(opts,'│')
    top='─'*len(plain)
    return '\n' + ansi_hunk_dec(opts,top)+ansi_hunk_dec(opts,'┐')+'\n' + mid+'\n' + ansi_hunk_dec(opts,top)+ansi_hunk_dec(opts,'┘')+'\n'

class Renderer:
    def __init__(self, opts):
        self.opts=opts; self.out=[]; self.minus_path=None; self.plus_path=None; self.git_context=False; self.header_done=False; self.in_hunk=False; self.oldn=1; self.newn=1; self.pending_minus=[]; self.pending_plus=[]; self.raw_inserted=False
    def flush_changes(self):
        n=max(len(self.pending_minus), len(self.pending_plus))
        spans=[]
        for i in range(n):
            if i < len(self.pending_minus) and i < len(self.pending_plus):
                spans.append(changed_spans(self.pending_minus[i][1], self.pending_plus[i][1]))
            else: spans.append(None)
        for i,(num,text) in enumerate(self.pending_minus):
            span=spans[i] if i<len(spans) else None
            self.emit_line('minus', text, num, None, span)
        for i,(num,text) in enumerate(self.pending_plus):
            span=spans[i] if i<len(spans) else None
            self.emit_line('plus', text, None, num, span)
        self.pending_minus=[]; self.pending_plus=[]
    def ensure_header(self):
        if not self.header_done and self.minus_path is not None and self.plus_path is not None:
            if not self.opts.get('raw') and not self.opts.get('color_only'):
                self.out.append(file_header(self.opts,self.minus_path,self.plus_path,self.git_context))
            self.header_done=True
    def emit_line(self, kind, text, oldn, newn, span=None):
        if self.opts.get('side_by_side') and not self.opts.get('color_only') and not self.opts.get('raw'):
            self.emit_side(kind,text,oldn,newn,span); return
        if self.opts.get('color_only'):
            if kind=='context': self.out.append(' '+style_zero(self.opts,text)+'\n')
            elif kind=='minus': self.out.append(style_minus_coloronly(self.opts,'-'+text,span)+'\n')
            else: self.out.append(style_plus_coloronly(self.opts,'+'+text,span)+'\n')
        elif self.opts.get('raw'):
            if not self.raw_inserted and not self.git_context and self.minus_path and self.plus_path and kind in ('minus','plus'):
                self.out.append('\n'+display_path(self.minus_path,False)+' '+self.opts.get('right_arrow','⟶  ')+' '+display_path(self.plus_path,False)+'\n')
                self.raw_inserted=True
            if kind=='context': self.out.append(' '+text+'\n')
            elif kind=='minus': self.out.append('\033[31m-'+text+RESET+'\n')
            else: self.out.append('\033[32m+'+text+RESET+'\n')
        else:
            marker=''
            if self.opts.get('keep_markers'): marker={'context':' ','minus':'-','plus':'+'}[kind]
            if kind=='context':
                self.out.append(line_prefix(self.opts,oldn,newn,'context') + (marker if marker else '') + style_zero(self.opts,text)+'\n')
            elif kind=='minus':
                self.out.append(line_prefix(self.opts,oldn,newn,'minus') + style_minus(self.opts,text,span,marker=marker)+'\n')
            else:
                self.out.append(line_prefix(self.opts,oldn,newn,'plus') + style_plus(self.opts,text,span,marker=marker)+'\n')
    def emit_side(self, kind, text, oldn, newn, span=None):
        width=self.opts.get('width') or 80
        col=max(8,(width-13)//2)
        def vispad(s,n):
            return s + ' '*max(0,n-len(strip_ansi(s)))
        if kind=='context':
            left=style_zero(self.opts,text); right=style_zero(self.opts,text)
            self.out.append(BLUE+'│'+GREY+fmt_num(oldn)+BLUE+'│'+vispad(left,col)+BLUE+'│'+GREY+fmt_num(newn)+BLUE+'│'+right+'\n')
        elif kind=='minus':
            left=style_minus(self.opts,text,span); blank=' '*col
            self.out.append(BLUE+'│'+REDNUM+fmt_num(oldn)+BLUE+'│'+vispad(left,col)+BLUE+'│'+GREENNUM+fmt_num(None)+BLUE+'│'+RESET+blank+'\n')
        else:
            blank=' '*col; right=style_plus(self.opts,text,span)
            self.out.append(BLUE+'│'+REDNUM+fmt_num(None)+BLUE+'│'+RESET+blank+BLUE+'│'+GREENNUM+fmt_num(newn)+BLUE+'│'+right+'\n')
    def process(self, lines):
        for raw in lines:
            line=chomp(raw); plain=strip_ansi(line)
            if plain.startswith('diff --git '):
                self.flush_changes(); self.minus_path=self.plus_path=None; self.header_done=False; self.git_context=True; self.in_hunk=False; self.raw_inserted=False
                if self.opts.get('raw') or self.opts.get('color_only'): self.out.append(raw)
                parts=plain.split()
                if len(parts)>=4: self.minus_path=parts[2]; self.plus_path=parts[3]
                continue
            if plain.startswith(('index ','new file mode ','deleted file mode ','similarity index ','rename from ','rename to ','copy from ','copy to ','old mode ','new mode ')):
                if self.opts.get('raw') or self.opts.get('color_only'): self.out.append(raw)
                continue
            if plain.startswith('--- '):
                self.flush_changes(); self.minus_path=plain[4:]; self.in_hunk=False
                if self.opts.get('raw') or self.opts.get('color_only'): self.out.append(raw)
                continue
            if plain.startswith('+++ '):
                self.plus_path=plain[4:]
                self.ensure_header()
                if self.opts.get('raw') or self.opts.get('color_only'): self.out.append(raw)
                continue
            if plain.startswith('@@'):
                self.flush_changes(); self.ensure_header(); self.in_hunk=True
                self.oldn,self.newn,ctx=parse_hunk_header(raw)
                if self.opts.get('raw') or self.opts.get('color_only'):
                    self.out.append(raw)
                else:
                    self.out.append(hunk_box(self.opts,self.newn,ctx,raw))
                continue
            if self.in_hunk and plain.startswith(' ') and not plain.startswith('  '):
                self.flush_changes(); text=plain[1:]
                self.emit_line('context', text, self.oldn, self.newn)
                self.oldn+=1; self.newn+=1; continue
            if self.in_hunk and plain.startswith('-') and not plain.startswith('---'):
                text=plain[1:]; self.pending_minus.append((self.oldn,text)); self.oldn+=1; continue
            if self.in_hunk and plain.startswith('+') and not plain.startswith('+++'):
                text=plain[1:]; self.pending_plus.append((self.newn,text)); self.newn+=1; continue
            if self.in_hunk and plain.startswith('\\'):
                self.flush_changes(); self.out.append(raw); continue
            self.flush_changes()
            # Outside recognized diff sections: pass through.
            if raw.endswith('\n'): self.out.append(raw)
            else: self.out.append(raw+'\n')
        self.flush_changes()
        return ''.join(self.out)

def render_diff(text, opts):
    return Renderer(opts).process(text.splitlines(True))

def is_probably_diff(text):
    return any(l.startswith(('diff --git ','--- ','@@ ')) for l in text.splitlines())

# file-to-file diff support
def git_blob_hash(content):
    if isinstance(content,str): content=content.encode()
    return hashlib.sha1(b'blob '+str(len(content)).encode()+b'\0'+content).hexdigest()[:7]

def label_path(p): return str(p).lstrip('/')

def make_file_diff(a,b, color_headers=False):
    pa=Path(a); pb=Path(b)
    try: ba=pa.read_bytes(); bb=pb.read_bytes()
    except Exception:
        return None
    if ba==bb: return ''
    ta=ba.decode('utf-8','replace').splitlines(True)
    tb=bb.decode('utf-8','replace').splitlines(True)
    la=label_path(a); lb=label_path(b)
    lines=[]
    if color_headers:
        lines.append(f'\033[1mdiff --git a/{la} b/{lb}\033[m\n')
        lines.append(f'\033[1mindex {git_blob_hash(ba)}..{git_blob_hash(bb)} 100644\033[m\n')
        lines.append(f'\033[1m--- a/{la}\033[m\n')
        lines.append(f'\033[1m+++ b/{lb}\033[m\n')
    else:
        lines.append(f'diff --git a/{la} b/{lb}\n')
        lines.append(f'index {git_blob_hash(ba)}..{git_blob_hash(bb)} 100644\n')
        lines.append(f'--- a/{la}\n')
        lines.append(f'+++ b/{lb}\n')
    for l in difflib.unified_diff(ta,tb,fromfile='',tofile='',n=3,lineterm=''):
        if l.startswith('---') or l.startswith('+++'): continue
        if not l.endswith('\n'): l += '\n'
        if color_headers and l.startswith('@@'):
            l='\033[36m'+l.rstrip('\n')+'\033[m\n'
        elif color_headers and l.startswith('-'):
            l='\033[31m'+l.rstrip('\n')+'\033[0m\n'
        elif color_headers and l.startswith('+'):
            l='\033[32m'+l.rstrip('\n')+'\033[0m\n'
        lines.append(l)
    return ''.join(lines)

def render_blame(text, opts):
    out=[]; matched=False
    bg='\033[48;2;0;0;0m'
    now=datetime.datetime.now(datetime.timezone.utc)
    for line in text.splitlines(True):
        raw=chomp(line)
        m=re.match(r'([0-9a-fA-F]{7,40}) \((.*?)\s+(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} [+-]\d{4})\s+(\d+)\) ?(.*)$', raw)
        if not m:
            out.append(line); continue
        matched=True
        commit, author, ts, num, code=m.groups()
        author=author.rstrip()
        try:
            dt=datetime.datetime.strptime(ts,'%Y-%m-%d %H:%M:%S %z')
            days=(now-dt).days
            if days>=730: rel=f'{days//365} years ago'
            elif days>=365: rel='1 year ago'
            elif days>=60: rel=f'{days//30} months ago'
            elif days>=30: rel='1 month ago'
            elif days>=2: rel=f'{days} days ago'
            elif days==1: rel='1 day ago'
            else: rel='today'
        except Exception: rel=ts[:10]
        meta=f'{rel:<15} {author:<15.14} {commit[:8]}'
        out.append(bg+meta+RESET+bg+'│'+RESET+bg+fmt_num(int(num))+RESET+bg+'│'+RESET+bg+text_color(opts)+(' '+code if code and not code.startswith(' ') else code)+RESET+bg+'\033[0K'+RESET+'\n')
    return ''.join(out) if matched else None

def show_config(opts):
    txt=data('show_config_no_gitconfig.txt')
    # Adjust a few booleans to reflect command-line flags in an approximate way.
    if opts.get('line_numbers'):
        txt=txt.replace('line-numbers                  = false','line-numbers                  = true')
    if opts.get('side_by_side'):
        txt=txt.replace('side-by-side                  = false','side-by-side                  = true')
    return txt

def main(argv):
    opts,pos,err=parse_args(argv)
    if err:
        rc,out,er=err; sys.stdout.write(out); sys.stderr.write(er); return rc
    read_config(opts)
    if opts.get('version'):
        sys.stdout.write('delta 0.18.2\n'); return 0
    if opts.get('help')=='long': sys.stdout.write(data('help_long.txt')); return 0
    if opts.get('help')=='short': sys.stdout.write(data('help_short.txt')); return 0
    if opts.get('list_syntax_themes'): sys.stdout.write(data('list_syntax_themes.txt')); return 0
    if opts.get('list_languages'): sys.stdout.write(data('list_languages.txt')); return 0
    if opts.get('show_colors'): sys.stdout.write(data('show_colors.txt')); return 0
    if opts.get('show_syntax_themes'): sys.stdout.write(data('show_syntax_themes.txt')); return 0
    if opts.get('show_themes'):
        sys.stderr.write('No themes found. Please see https://dandavison.github.io/delta/custom-themes.html.\n'); return 2
    if opts.get('show_config'): sys.stdout.write(show_config(opts)); return 0
    if opts.get('generate_completion'):
        shell=opts.get('generate_completion')
        fn=f'completion_{shell}.txt'
        p=DATA_DIR/fn
        if p.exists(): sys.stdout.write(p.read_text(errors='replace')); return 0
        sys.stderr.write(f"invalid value '{shell}' for '--generate-completion <GENERATE_COMPLETION>'\n"); return 2
    # diff-highlight and diff-so-fancy presets
    if opts.get('diff_highlight'):
        opts['raw']=True; opts['keep_markers']=False
    if len(pos)==2:
        # original reports this git-ish message and exits 0 if first path cannot be accessed.
        if not Path(pos[0]).exists() or not Path(pos[1]).exists():
            sys.stderr.write(f"git diff: error: Could not access '{pos[0]}'\n"); return 0
        fd=make_file_diff(pos[0],pos[1], color_headers=(opts.get('raw') or opts.get('color_only')))
        if fd is None: return 0
        if fd=='': return 0
        if opts.get('raw'):
            # Generated diff is already git-colored similarly to --raw file mode.
            sys.stdout.write(fd); return 1
        sys.stdout.write(render_diff(fd, opts)); return 1
    # Single file operand is accepted but does not itself cause output.
    try:
        text=sys.stdin.read()
    except KeyboardInterrupt:
        return 130
    if not text: return 0
    if is_probably_diff(strip_ansi(text)):
        sys.stdout.write(render_diff(text, opts)); return 0
    b=render_blame(text, opts)
    if b is not None: sys.stdout.write(b); return 0
    sys.stdout.write(text); return 0

if __name__=='__main__':
    try:
        raise SystemExit(main(sys.argv[1:]))
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        raise SystemExit(0)
